/// @brief Owned manufacturer data. Release its contents with simpleble_manufacturer_data_release().
final class simpleble_manufacturer_data_t extends ffi.Struct {
  @ffi.Uint16()
  external int manufacturer_id;

  @ffi.Size()
  external int data_length;

  external ffi.Pointer<ffi.Uint8> data;

  static ffi.Pointer<simpleble_manufacturer_data_t> $allocate(
    ffi.Allocator $allocator, {
    required int manufacturer_id,
    required int data_length,
    required ffi.Pointer<ffi.Uint8> data,
  }) => $allocator<simpleble_manufacturer_data_t>()
    ..ref.manufacturer_id = manufacturer_id
    ..ref.data_length = data_length
    ..ref.data = data;
}

